def metric(data: pd.DataFrame) -> float:
    import numpy as np
    import pandas as pd

    if data is None or len(data) == 0:
        return 0.5

    hits = 0
    total = 0
    for _, row in data.iterrows():
        try:
            a = np.asarray(list(row['option_a_ratings']), dtype=float).ravel()
            b = np.asarray(list(row['option_b_ratings']), dtype=float).ravel()
        except Exception:
            continue
        if a.size == 0 or a.size != b.size:
            continue
        ca = float(np.sum(a))
        cb = float(np.sum(b))
        if abs(ca - cb) != 1.0:
            continue
        # strictly nested pairs only (the difference is a single shared cue)
        nested = bool(np.all(a <= b + 1e-9)) or bool(np.all(b <= a + 1e-9))
        if not nested:
            continue
        # high base-count region only: the smaller option already carries >= 2 flags
        if min(ca, cb) < 2.0:
            continue
        try:
            resp = int(row['response'])
        except Exception:
            continue
        if resp not in (0, 1):
            continue
        better = 0 if ca < cb else 1  # fewer warning flags is the 'correct' option
        total += 1
        if resp == better:
            hits += 1

    if total == 0:
        return 0.5
    return float(hits) / float(total)

